def agent(obs):
    try:
        s = obs.get("step")
        if s is None:
            s = int(obs.get("day", 0)) * 24 + int(obs.get("hour", 0))
        s = int(s)
        # REPLAY ALIGNMENT FIX: the action stored at step i of the
        # episode JSON was generated from the observation at step i-1
        # (its market effects are already visible at step i), so when
        # the agent receives obs at step s it must return ACTIONS[s+1].
        j = s + 1
        a = ACTIONS[j] if 0 <= j < len(ACTIONS) else (ACTIONS[-1] if ACTIONS else {})
        return {"farmer": a.get("farmer") or ["PASS"],
                "hands": a.get("hands") or [],
                "market": a.get("market") or []}
    except Exception:
        return {"farmer": ["PASS"], "hands": [], "market": []}


# V88: ymg_aq tape + final liquidation (fires only on the last step).
_v88_tape = agent


def agent(obs):
    try:
        step = int(obs.get("step") or 0)
    except Exception:
        step = 0
    if step < 719:
        return _v88_tape(obs)
    try:
        shed = (obs.get("private") or {}).get("shed") or {}
    except Exception:
        shed = {}
    prices = (obs.get("market") or {}).get("prices") or {}
    market = [["SELL", item, int(qty)] for item, qty in shed.items()
              if isinstance(qty, (int, float)) and int(qty) > 0 and int(prices.get(item, 0)) >= 2]
    market.sort(key=lambda o: -int(prices.get(o[1], 0)) * o[2])
    return {"farmer": ["PASS"], "hands": [], "market": market}
